"""Swift Book-led value semantics, optionality, protocols, and concurrency."""
from build import S, lesson as L


def lessons():
 return [
 L('toolchain','Swift scripts and packages','Swift can interpret scripts or compile executables. Swift Package Manager organizes targets and dependencies; swift build and swift test are distinct operations. The course uses Swift 6 language mode and no application frameworks. Top-level script statements are separate from @main entry types.',
 S('$ swift ~build~','Builds the Swift package','Runs all tests|Creates an iOS application','The package build command compiles its targets.','test|run','What action is requested?'),
 S('$ swift package ~init~ --type executable','Creates an executable package skeleton','Publishes a package|Runs existing tests','init writes package metadata and starter source.','resolve|show-dependencies','What is created?'),
 S('$ ~swiftc~ Main.swift -o app','Compiles Main.swift into an executable','Runs a REPL|Runs the executable immediately','swiftc is the compiler driver; -o names the output file.','swift package|swift test','What does this command do?'),
 S('~print~("${word}")','${word}','No output|Compile error','A top-level script can call the standard print function.','String|type(of:)')),
 L('bindings','Let, var, and explicit numeric conversion','let defines a constant binding and var a variable. Swift infers static types but does not silently mix arbitrary numeric types. Integer division truncates. Overflow normally traps; wrapping operators such as &+ explicitly request modular arithmetic.',
 S('var n = ${n}; n ~+=~ 1; print(n)','${next}','${n}|Compile error','Swift uses compound assignment; it has no ++ operator.','-=|='),
 S('let small:Int8 = ${n}; let n = ~Int(small)~; print(n+1)','${next}','${n}|Compile error','The initializer explicitly converts the integer type.','small as String|String(small)'),
 S('print(${n} ~/~ ${m})','${div}','${mul}|${add}','Two integer operands produce a truncated integer quotient.','*|+'),
 S('let n:UInt8 = 255; print(n ~&+~ 1)','0','Traps on overflow|Compile error','The wrapping addition operator explicitly permits modular overflow.','+|-')),
 L('text','Strings, characters, and interpolation','Swift String models Unicode text and counts extended grapheme clusters. Its indices are String.Index values, not integer offsets. Interpolation embeds expressions. UTF-8 views expose bytes when byte-oriented processing is intended.',
 S('let name = "${word}"; print(~"Hello \\(name)"~)','Hello ${word}','Hello name|Compile error','Backslash-parenthesis interpolation inserts the value of name.','"Hello name"|name'),
 S('print("${word}".~uppercased()~)','${upper}','${word}|Compile error','uppercased returns another string.','lowercased()|isEmpty'),
 S('let text = "e\u0301"; print(text.~count~)','1','2|3','The letter plus combining accent forms one extended grapheme cluster.','unicodeScalars.count|utf8.count'),
 S('let text = "${word}"; print(text[~text.startIndex~])','${first}','${word}|Compile error','A String.Index identifies a valid character boundary.','0|text.endIndex')),
 L('control','Conditions and exhaustive switch','Conditions require Bool. switch has no implicit fall-through and must cover the value space. Ranges support interval matching. if let and guard let, introduced later, bind optional values while checking presence.',
 S('let n = ${n}; print(n ~>~ 0 ? "yes" : "no")','yes','no|Compile error','The positive value selects the first conditional result.','<|=='),
 S('let n = ${n}; switch n {case 1...100:print("inside"); ~default~:print("outside")}','inside','outside|Compile error','The generated value lies in the closed interval and the default ensures coverage.','else|otherwise'),
 S('var n = 0; let ok = false ~&&~ {n+=1;return true}(); print(n)','0','1|Compile error','Short-circuiting avoids the closure call.','|||=='),
 S('let n = 1; switch n {case 1:print("one");case 2:print("two");~default~:break}','one','one\ntwo|Compile error','Swift switch cases do not implicitly continue into the next case.','else|otherwise')),
 L('loops','Ranges and value iteration','Closed ranges include their endpoint, while half-open ranges exclude it. for-in iterates values; changing a local copy does not rewrite an array. enumerate with enumerated() when both index and value are needed. break and continue control loop execution.',
 S('print((0~..<~${n}).count)','${n}','${next}|0','The half-open range includes zero and excludes ${n}.','...|>..'),
 S('print((1~...~${n}).count)','${n}','${prev}|0','The closed range includes both ends.','..<|>..'),
 S('var n = 0; for i in 0..<3 {if i==1 {~continue~}; n+=1}; print(n)','2','1|3','Only the middle iteration skips the increment.','break|return'),
 S('var a = [${n}]; for i in a.indices {a[i]+=1}; print(~a[0]~)','${next}','${n}|Compile error','indices supplies valid positions for indexed mutation.','a.count|0')),
 L('functions','Argument labels and inout','External argument labels make Swift APIs read naturally; _ suppresses a label. Defaults supply omitted arguments. inout temporarily provides exclusive access for mutation, and the call uses &. Swift enforces exclusivity rather than allowing arbitrary overlapping inout access.',
 S('func bump(~_~ n:Int)->Int {n+1}\nprint(bump(${n}))','${next}','${n}|Compile error','The underscore removes the external argument label.','value|n'),
 S('func greet(name:String = "${word}")->String {name}\nprint(~greet()~)','${word}','Empty string|Compile error','The omitted named argument uses the default.','greet(name:"")|greet'),
 S('func bump(_ n:~inout Int~){n+=1}\nvar n = ${n}; bump(&n); print(n)','${next}','${n}|Compile error','inout and & permit the function to update the caller value.','Int|let Int'),
 S('func size(limit n:Int)->Int {n}\nprint(size(~limit:${n}~))','${n}','Compile error|0','limit is the external label and n is the internal parameter name.','n:${n}|${n}')),
 L('optionals','Optional binding and nil coalescing','Optional<T> contains a value or nil. if let unwraps only when present. ?? supplies a fallback and ?. chains access conditionally. Forced unwrap ! traps for nil and should follow a demonstrated invariant, not wishful thinking.',
 S('let n:Int? = nil; print(n ~??~ ${n})','${n}','nil|Compile error','Nil coalescing supplies the fallback value.','|||?:'),
 S('let name:String? = "${word}"; if ~let text = name~ {print(text)}','${word}','No output|Compile error','Optional binding introduces a non-optional String in the branch.','text = name|var text:String = name'),
 S('let text:String? = nil; print(text~?.~count ?? 0)','0','Traps|Compile error','Optional chaining returns nil without accessing a missing string.','!.|.'),
 S('let n:Int? = ${n}; print(n~!~)','${n}','Optional(${n})|Compile error','This optional is known to contain a value, so the force unwrap succeeds.','| ?? 0')),
 L('guard','Guard clauses and early exits','guard requires its else branch to leave the current scope with return, throw, break, or another diverging action. Successful bindings remain available after the guard. This supports a readable normal path after precondition checks.',
 S('func label(_ x:String?)->String {guard let text = x else {~return~ "missing"};return text}\nprint(label("${word}"))','${word}','missing|Compile error','The guard binds text for the remainder of the function.','print|continue'),
 S('func size(_ x:Int?)->Int {guard let n = x else {return ${n}};return n}\nprint(size(~nil~))','${n}','0|Compile error','An absent optional takes the early fallback return.','0|1'),
 S('func positive(_ n:Int)->Bool {guard n>0 else {return false};return ~true~}\nprint(positive(${n}))','true','false|Compile error','The successful path continues after the guard.','false|nil'),
 S('func label(_ x:String?)->String {guard let text = x,~!text.isEmpty~ else {return "missing"};return text}\nprint(label("${word}"))','${word}','missing|Compile error','Guard conditions check both presence and nonempty content.','text.isEmpty|false')),
 L('collections','Arrays, dictionaries, and sets','Swift collections have value semantics. Dictionary lookup returns an optional; a default subscript can support updates. Arrays preserve order and sets enforce uniqueness. Copy-on-write is an optimization behind observable value behavior, not shared mutation semantics.',
 S('var a = [${n}]; a.~append~(${m}); print(a.count)','2','1|Compile error','append extends the mutable array value.','contains|remove(at:)'),
 S('let m = ["${word}":${n}]; print(m[~"${word}"~] ?? 0)','${n}','0|Compile error','Dictionary subscripting returns the optional mapped value.','"missing"|"other"'),
 S('let s:Set<String>=["${word}","${word}"]; print(s.~count~)','1','2|Compile error','A set stores one instance of each equal value.','capacity|isEmpty'),
 S('var counts:[String:Int] = [:]; counts["${word}",~default:0~]+=${n}; print(counts["${word}"] ?? 0)','${n}','0|Compile error','The default subscript creates an initial value for an absent key during mutation.','0|fallback:0')),
 L('value-types','Structs and value semantics','Struct assignment copies observable value state. A mutating method may change self or stored properties. let on a struct prevents mutation through that binding. Classes introduce identity, addressed separately.',
 S('struct Point {var x:Int}\nvar a = Point(x:${n}); var b = a; b.x = 0; print(~a.x~)','${n}','0|Compile error','The copied struct has independent integer state.','b.x|0'),
 S('struct Counter {var n:Int; ~mutating~ func bump(){n+=1}}\nvar c = Counter(n:${n}); c.bump(); print(c.n)','${next}','${n}|Compile error','mutating permits a struct method to update stored properties.','static|class'),
 S('struct Item {let name:String}\nlet item = ~Item(name:"${word}")~; print(item.name)','${word}','Compile error|Empty string','A memberwise initializer supplies the stored property value.','Item("${word}")|Item()'),
 S('var a = [${n}]; var b = a; b[0] = 0; print(~a[0]~)','${n}','0|Compile error','Array mutation preserves independent value behavior after assignment.','b[0]|0')),
 L('properties','Computed properties and observers','Stored properties hold values; computed properties execute accessors. didSet observes assignment and is useful for reactions, not a universal validation barrier. Static properties belong to the type. Property wrappers are a separate abstraction rather than magic storage.',
 S('struct Item {var n:Int; var double:Int {~n*2~}}\nprint(Item(n:${n}).double)','${double}','${n}|Compile error','The computed getter returns twice the stored value.','n|0'),
 S('struct Item {static let name = "${word}"}\nprint(~Item.name~)','${word}','Compile error|Empty string','A static property is accessed on the type.','Item().name|Item.name()'),
 S('struct Counter {var n:Int {~didSet~ {print(n)}}}\nvar c = Counter(n:0); c.n = ${n}','${n}','0\n${n}|No output','The observer runs for this post-initialization assignment.','willSet|set'),
 S('struct Item {var n:Int; var value:Int {get {n} set {n = ~newValue~}}}\nvar x = Item(n:0); x.value = ${n}; print(x.n)','${n}','0|Compile error','newValue is the implicit name of a custom setter input.','oldValue|value')),
 L('enums','Associated values and exhaustive models','Enums model mutually exclusive cases and can attach differently typed payloads. switch binds payloads and must be exhaustive. Raw values are a separate representation feature; their initializer can fail for unknown values.',
 S('enum State {case ready(Int);case idle}\nlet s = State.ready(${n}); switch s {case ~.ready(let n)~:print(n);case .idle:print(0)}','${n}','0|Compile error','The case pattern extracts the associated integer.','.ready|.idle'),
 S('enum Mode:String {case read = "r";case write = "w"}\nprint(Mode.read.~rawValue~)','r','read|Compile error','The raw value is the explicitly declared string representation.','hashValue|self'),
 S('enum Mode:String {case read = "r"}\nprint(Mode(rawValue:~"missing"~)==nil)','true','false|Compile error','An unrecognized raw value fails the optional initializer.','"r"|"read"'),
 S('enum Result {case ok(String);case missing}\nlet r = Result.ok("${word}"); if case ~.ok(let text)~ = r {print(text)}','${word}','No output|Compile error','if case matches one alternative and binds its payload.','.missing|.ok')),
 L('classes','Reference identity and inheritance','Classes share identity through references. A let class binding cannot be rebound, but mutable object properties can still change. === tests object identity. Inheritance and overrides support polymorphism; prefer explicit final where extension is not intended.',
 S('class Box {var n = ${n}}\nlet a = Box(); let b = a; b.n = 0; print(~a.n~)','0','${n}|Compile error','Both bindings reference the same mutable object.','a.n+1|1'),
 S('class Box {}\nlet a = Box(); let b = a; print(a ~===~ b)','true','false|Compile error','Identity equality checks whether both references denote one object.','!==|=='),
 S('class Base {func text()->String {"base"}}\nclass Child:Base {~override~ func text()->String {"${word}"}}\nlet x:Base = Child(); print(x.text())','${word}','base|Compile error','An override is dynamically selected for the Child instance.','static|final'),
 S('~final~ class Item {}','Prevents subclassing Item','Makes every object immutable|Creates one singleton','final restricts inheritance but does not automatically freeze instance state.','open|public','What does this modifier ensure?')),
 L('protocols','Protocols, extensions, and conformance','Protocols express requirements and types explicitly declare conformance. Extensions can add default implementations. Protocol requirements participate in dynamic dispatch through an existential; extension-only helpers have different dispatch behavior. Keep the API contract visible.',
 S('protocol Named {var name:String {get}}\nstruct Item:~Named~ {let name:String}\nprint(Item(name:"${word}").name)','${word}','Compile error|Empty string','The stored property satisfies the protocol getter requirement.','String|Int'),
 S('protocol Sized {func size()->Int}\nextension Sized {func size()->Int {${n}}}\nstruct Item:Sized {}\nprint(Item().~size()~)','${n}','0|Compile error','The extension supplies a default implementation of a requirement.','size|hashValue'),
 S('extension String {var tagged:String {"["+self+"]"}}\nprint("${word}".~tagged~)','[${word}]','${word}|Compile error','The extension adds a computed property without storing extra state.','description|count'),
 S('protocol Named {var name:String {get}}\nstruct Item:Named {let name:String}\nlet x:~any Named~ = Item(name:"${word}"); print(x.name)','${word}','Compile error|Empty string','any Named stores a value behind an existential protocol interface.','Named.Type|Any')),
 L('closures','Closures and capture lists','Closures can be passed as function values and trailing arguments. They capture surrounding state; an explicit capture list can snapshot values or weaken references. @escaping means a function may retain the closure after returning, which makes lifetime and reference cycles important.',
 S('let f:(Int)->Int = {~$0+1~}; print(f(${n}))','${next}','${n}|Compile error','$0 is the first shorthand closure parameter.','$0|0'),
 S('print(["${word}"].~map~ {$0.count}[0])','${length}','0|Compile error','map transforms the element with the closure.','filter|forEach'),
 S('var n = ${n}; let f = {~[n]~ in n}; n+=1; print(f())','${n}','${next}|Compile error','The capture list snapshots the integer value at closure creation.','|[self]'),
 S('// Function signature:\nfunc store(_ work:~@escaping~ ()->Void) {}','May retain work beyond this function call','Automatically runs work concurrently|Requires a throwing closure','@escaping describes closure lifetime, not scheduling.','@Sendable|','What does the annotation permit?')),
 L('generics','Generic constraints and opaque results','Generic type parameters preserve relationships chosen by a caller. Constraints expose required operations. some Protocol hides one concrete result type selected by an implementation; any Protocol packages an existential that may hold different conforming types. These have different contracts.',
 S('func identity<T>(_ x:~T~)->T {x}\nprint(identity("${word}"))','${word}','Compile error|Empty string','The same T links the input and output types.','Any|String'),
 S('func same<T:~Equatable~>(_ a:T,_ b:T)->Bool {a==b}\nprint(same(${n},${n}))','true','false|Compile error','Equatable supplies the equality operation used by the generic function.','AnyObject|CustomStringConvertible'),
 S('func values()->~some Collection<Int>~ {[${n}]}\nprint(values().count)','1','${n}|Compile error','The opaque return exposes collection behavior while hiding its concrete array type.','Int|Any'),
 S('func size<C:Collection>(_ xs:~C~)->Int {xs.count}\nprint(size([${n},${m}]))','2','1|Compile error','The generic Collection constraint supplies count without specifying Array.','Int|Any')),
 L('errors','Throwing functions and deferred cleanup','throws marks a function that can propagate errors; try acknowledges a throwing call. do/catch handles failures. try? converts a thrown error to nil, while try! traps on error. defer runs cleanup when the current scope exits, in reverse registration order.',
 S('enum Failure:Error {case invalid}\nfunc read() throws -> Int {throw Failure.invalid}\nprint((~try?~ read()) ?? ${n})','${n}','Traps|Compile error','try? turns the thrown failure into an absent optional.','try!|try'),
 S('enum Failure:Error {case invalid}\ndo {throw Failure.invalid} ~catch~ {print("handled")}','handled','Uncaught error|Compile error','catch receives the error thrown from the do block.','else|finally'),
 S('func work(){defer {print("done")};print("${word}")}\n~work()~','${word}\ndone','done\n${word}|Compile error','defer runs at function exit after the ordinary statement.','print("done")|print("${word}")'),
 S('func work(){defer {print("first")}; ~defer~ {print("second")}}\nwork()','second\nfirst','first\nsecond|Compile error','Deferred actions run in reverse registration order.','do|if true')),
 L('arc','ARC, weak references, and cycles','ARC manages class instance lifetimes through strong references. weak references are non-owning optionals and become nil when the instance dies. unowned assumes a valid lifetime and can trap if that assumption fails. Closures retained by their captured owner can form strong cycles.',
 S('class Item {}\nvar owner:Item? = Item(); ~weak~ var observer = owner; owner = nil; print(observer==nil)','true','false|Compile error','The weak reference does not keep the instance alive and becomes nil.','|unowned'),
 S('class Item {deinit {print("released")}}\nvar owner:Item? = Item(); ~owner = nil~','released','No output|Compile error','Dropping the last strong reference permits deterministic deinitialization here.','print("held")|_ = owner'),
 S('class Item {}\nvar a:Item? = Item(); let b = a; a = nil; print(~b != nil~)','true','false|Compile error','b still holds a strong reference to the same object.','b == nil|a != nil'),
 S('// Inside a class that retains handler:\nhandler = { ~[weak self]~ in self?.refresh() }','Avoids a strong self capture in this closure','Keeps self alive forever|Makes refresh asynchronous','A weak capture lets self deallocate and uses optional access when invoked later.','[self]|','What lifetime property does the capture list provide?')),
 L('async','Async functions and structured child work','async permits suspension and await marks a possible suspension point. It does not by itself move work to a background thread. async let starts a structured child whose lifetime is bounded by scope. Sequential awaits differ from starting independent children before awaiting their results.',
 S('func value() ~async~ -> Int {${n}}','An asynchronous function returning Int','Automatically creates a new OS thread|A throwing function','async changes the calling contract without specifying an executor thread.','throws|','What does the modifier declare?'),
 S('// Inside an async function:\nfunc value() async -> Int {${n}}\nlet n = ~await~ value(); print(n)','${n}','Compile error|A task description','await obtains the result at a possible suspension point.','try|yield'),
 S('// Inside an async function:\nfunc value() async -> Int {${n}}\n~async let~ n = value(); print(await n)','${n}','Compile error|A task description','async let creates a structured child computation whose result is awaited.','let|var'),
 S('// Inside an async function:\nasync let a:Int = ${n}\nasync let b:Int = ${m}\nlet pair = ~await~ (a,b)\nprint(pair.0+pair.1)','${add}','${mul}|Compile error','Awaiting both child values makes them available for the sum.','try|yield')),
 L('actors','Actor isolation and cancellation','Actors isolate mutable state; access across isolation may require await. Suspension permits reentrancy, so assumptions spanning an await need rechecking. Sendable describes safe transfer across concurrency domains. Cancellation is cooperative and Task.checkCancellation throws when requested.',
 S('~actor~ Counter {var n = 0;func bump(){n+=1}}','Serializes isolated state access','Makes all calls synchronous|Freezes n','An actor protects its isolated mutable state; it is not an immutable class.','class|struct','What concurrency boundary is declared?'),
 S('// Inside an async function:\nactor Counter {func value()->Int {${n}}}\nlet c = Counter(); print(~await~ c.value())','${n}','Compile error|Always zero','A cross-actor call awaits access to the isolated method.','try|yield'),
 S('struct Message:~Sendable~ {let count:Int}','Declares safe transfer of this value across concurrency domains','Makes count atomic|Starts a new task','The stored immutable Int supports checked Sendable conformance.','Error|AnyObject','What contract is expressed?'),
 S('// Inside an async throwing function:\ntry Task.~checkCancellation()~','Throws CancellationError if the task is cancelled','Forcibly terminates every child thread|Always suspends','The explicit check cooperatively observes cancellation; it does not forcibly stop unrelated work.','yield()|sleep(nanoseconds:1)','What does this check do?')),
 ]
